CREATE TABLE users(id serial PRIMARY KEY, username text UNIQUE, role text, is_active int DEFAULT 1, password_hash text, salt text);
CREATE TABLE user_activity_log(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),username TEXT NOT NULL,action TEXT NOT NULL,details TEXT,ip_address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(key text PRIMARY KEY, value text);
CREATE TABLE sales(id serial PRIMARY KEY, invoice_no text UNIQUE, total float8, payment float8, change_amount float8, customer_id int, status text, payment_type text, discount_amount float8, cogs float8, gross_profit float8, net_profit float8, created_by text, created_at timestamp);
CREATE TABLE sale_items(id serial PRIMARY KEY, sale_id int, product_id int, variant_id int, product_name text, qty float8, price float8, total float8, cost float8, wholesale_regular_price float8, wholesale_savings float8, wholesale_tier_min_qty int, wholesale_unit_label text, location_id int, location text, batch_no text, expire_date text, refunded_qty float8 DEFAULT 0, refund_reason text);
CREATE TABLE products(id int PRIMARY KEY, stock float8, cost float8 DEFAULT 0, sold_by text, last_updated timestamp);
CREATE TABLE product_variants(id int PRIMARY KEY, product_id int, stock int, active int DEFAULT 1, updated_at timestamp);
CREATE TABLE customers(id int PRIMARY KEY, current_balance float8, credit_limit float8, total_visit int DEFAULT 0, total_spent float8 DEFAULT 0);
CREATE TABLE credit_sales(id serial PRIMARY KEY, sale_id int, invoice_no text, customer_id int, total_amount float8, paid_amount float8, balance_amount float8, sale_date text, due_date text, status text, notes text);
CREATE TABLE credit_payments(credit_sale_id int, customer_id int, amount float8, payment_date text, payment_method text, note text);
CREATE TABLE credit_adjustments(customer_id int, credit_sale_id int, amount float8, adjustment_type text, reason text, created_by text);
CREATE TABLE stock_movements(id serial PRIMARY KEY, product_id int, variant_id int, type text, quantity float8, old_stock float8, new_stock float8, reason text, reference text, created_by text, location text, created_at timestamp DEFAULT CURRENT_TIMESTAMP, notes text);
CREATE TABLE product_locations(id serial PRIMARY KEY, product_id int, location text, batch_no text, expire_date text, quantity float8, last_updated timestamp DEFAULT CURRENT_TIMESTAMP, UNIQUE(product_id,location,batch_no,expire_date));
CREATE TABLE variant_stock_batches(product_id int, variant_id int, location text, batch_no text, expire_date text, quantity int, expiry_unknown int, UNIQUE(product_id,variant_id,location,batch_no,expire_date));
CREATE TABLE variant_batch_changes(movement_id int,product_id int,variant_id int,location text,batch_no text,expire_date text,delta int,expiry_unknown int);
